{
  "action": "settings",
  "settings": {
    "notifications": {
      "email": {
        "VettingUpdates": true,
        "InterviewAlerts": true,
        "PaymentAlerts": true
      },
      "whatsapp": {
        "VettingUpdates": false,
        "InterviewAlerts": true,
        "PaymentAlerts": true
      }
    }
  }
}

{
  "requestId": "{{requestId}}",
  "sourcingRequired": true,
  "note": "Nobody on the platform fits this brief."
}

{
  "action": "pipeline",
  "talentId": "{{talentProfileId}}",
  "pipeline": [
    {
      "stageName": "Application Screening",
      "status": "completed",
      "decision": "Proceed"
    },
    {
      "stageName": "Behavioural Interview",
      "status": "in_progress"
    }
  ],
  "vettingStage": "Behavioural Interview",
  "auditAction": "Stage Decision: Application Screening",
  "auditDetails": "Decision: Proceed."
}

{
  "talentSkillAssessmentId": "{{talentSkillAssessmentId}}",
  "assessmentId": "{{assessmentId}}",
  "answers": {
    "q1": "a",
    "q2": [
      "b",
      "c"
    ],
    "q3": "I would start by reading the logs."
  }
}

{
  "entity": "question",
  "data": {
    "category_id": "{{assessmentCategoryId}}",
    "type": "multiple_choice",
    "question_text": "Which index type suits an equality lookup?",
    "options": [
      "btree",
      "gin",
      "gist"
    ],
    "correct_answer": "btree",
    "scoring_weight": 2,
    "max_score": 10
  }
}

{
  "interviewId": "{{interviewId}}",
  "approve": false,
  "note": "The client cannot move this week."
}

{
  "interviewId": "{{interviewId}}",
  "reason": "The role has been put on hold."
}

{
  "offerId": "{{offerId}}",
  "action": "request_revision",
  "note": "Rate is below the floor for this grade."
}

{
  "offerId": "{{offerId}}",
  "decision": "decline",
  "reason": "The start date does not work for me."
}

{
  "name": "Standard EOR agreement",
  "serviceType": "Hire Talent",
  "body": "This agreement is made between {{client_company}} and {{talent_name}}.\n\nThe engagement begins on the agreed start date and is governed by the terms set out below.",
  "status": "draft"
}

{
  "name": "IT and Ethics Policy",
  "type": "IT_Ethics_Policy",
  "isMandatory": true,
  "description": "Required of every candidate before deployment."
}

{
  "subject": "Payment has not arrived",
  "category": "Payments",
  "description": "My October payout has not landed."
}

{
  "subject": "Invoice query",
  "category": "Billing",
  "description": "Invoice KNG-9001 shows the wrong rate."
}

{
  "action": "dispute",
  "invoiceId": "{{invoiceId}}",
  "reason": "The rate does not match the contract."
}
